<?php use Hls\Http\View as V; ?><?php if($error): ?><div class="alert alert-error"><?= V::escape($error) ?></div><?php endif ?><section class="panel"><form method="post" class="form-grid"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><input type="hidden" name="version" value="<?= (int)$row['version'] ?>"><p>Customer: <?= V::escape($row['customer_name']) ?></p><label>Tanggal invoice<input name="invoice_date" type="date" value="<?= V::escape((string)$row['invoice_date']) ?>" required></label><label>Jatuh tempo<input name="due_date" type="date" value="<?= V::escape((string)($row['due_date']??'')) ?>"></label><?php foreach($lines as $l): ?><label>Deskripsi<input name="description[]" value="<?= V::escape($l['description']) ?>" required></label><label>Kuantitas<input name="quantity[]" type="number" min="0.001" step="0.001" value="<?= V::escape($l['quantity']) ?>" required></label><label>Harga<input name="unit_price[]" type="number" min="0" step="0.01" value="<?= V::escape($l['unit_price']) ?>" required></label><?php endforeach ?><label>Item baru<input name="description[]" placeholder="Deskripsi item baru"></label><label>Kuantitas baru<input name="quantity[]" type="number" min="0" step="0.001" value="0"></label><label>Harga baru<input name="unit_price[]" type="number" min="0" step="0.01" value="0"></label><button class="button button-primary">Simpan Perubahan</button></form></section>
